package com.hospital.ui;
import com.hospital.dao.UserDAO;import com.hospital.model.*;import com.hospital.service.*;
import java.io.Console;import java.math.BigDecimal;import java.sql.*;import java.time.*;import java.util.*;

/** Console adapter. Reads complete lines so numeric input never leaves a newline in Scanner. */
public class MainMenu {
 private final Scanner in=new Scanner(System.in);private final AuthService auth=new AuthService();private final PatientService patients=new PatientService();private final DirectoryService directory=new DirectoryService();private final AppointmentService appointments=new AppointmentService();private final ClinicalService clinical=new ClinicalService();private final BillingService billing=new BillingService();
 public void run(){while(true){User user=login();if(user==null)return;boolean loggedIn=true;while(loggedIn){show(user);String choice=ask("Choose: ");try{switch(choice){case "1"->patientMenu(user);case "2"->doctorMenu(user);case "3"->departmentMenu(user);case "4"->appointmentMenu(user);case "5"->recordMenu(user);case "6"->prescriptionMenu(user);case "7"->billingMenu(user);case "8"->reportMenu(user);case "9"->userMenu(user);case "10"->changePassword(user);case "0"->{loggedIn=false;System.out.println("Logged out.");}default->System.out.println("Choose a listed menu number.");}}catch(SQLException|RuntimeException e){System.out.println("Could not complete action: "+safe(e));}}}}
 private User login(){System.out.println("\n========================================\n       HOSPITAL MANAGEMENT PORTAL\n========================================");String username=ask("Username (or 0 to exit): ");if(username.equals("0"))return null;String password=password("Password: ");try{return auth.login(username,password);}catch(Exception e){System.out.println("Login failed. Check your username and password, and contact an administrator if your account is inactive.");return login();}}
 private String password(String prompt){Console console=System.console();if(console!=null){char[] chars=console.readPassword("%s",prompt);return chars==null?"":new String(chars);}return ask(prompt+" (input visible in IDE terminals): ");}
 private void show(User u){System.out.println("\nSigned in: "+u.username()+" ["+u.role()+"]");if(u.role()==Role.ADMIN||u.role()==Role.RECEPTIONIST)System.out.println("1 Patients");else if(u.role()==Role.DOCTOR)System.out.println("1 Patient lookup (permitted records)");if(u.role()!=Role.BILLING_STAFF)System.out.println("2 Doctors");if(u.role()==Role.ADMIN||u.role()==Role.RECEPTIONIST)System.out.println("3 Departments");if(u.role()!=Role.BILLING_STAFF)System.out.println("4 Appointments");if(u.role()==Role.ADMIN||u.role()==Role.DOCTOR)System.out.println("5 Medical records");if(u.role()==Role.ADMIN||u.role()==Role.DOCTOR)System.out.println("6 Prescriptions");if(u.role()==Role.ADMIN||u.role()==Role.BILLING_STAFF)System.out.println("7 Billing and payments");if(u.role()==Role.ADMIN||u.role()==Role.BILLING_STAFF)System.out.println("8 Reports");if(u.role()==Role.ADMIN)System.out.println("9 User management");System.out.println("10 Change password\n0 Logout");}
 private void patientMenu(User u)throws SQLException{System.out.println("Patients: 1 Register  2 Search/list  3 View by ID  4 Update  5 Deactivate");switch(ask("Choice: ")){case "1"->{long id=patients.register(u,ask("Full name: "),ask("Date of birth (YYYY-MM-DD): "),ask("Gender: "),ask("Phone: "),ask("Address: "),ask("Blood group (optional): "));System.out.println("Patient ID: "+id);}case "2"->{for(Patient p:patients.search(u,ask("Name, phone, or ID search: "),integer("Page: ")))System.out.println(p);}case "3"->System.out.println(patients.get(u,longValue("Patient ID: ")));case "4"->{long id=longValue("Patient ID: ");patients.update(u,id,ask("Full name: "),ask("Date of birth (YYYY-MM-DD): "),ask("Gender: "),ask("Phone: "),ask("Address: "),ask("Blood group: "));System.out.println("Updated.");}case "5"->{long id=longValue("Patient ID to deactivate: ");if(confirm())patients.deactivate(u,id);}default->System.out.println("No action.");}}
 private void doctorMenu(User u)throws SQLException{System.out.println("Doctors: 1 Add  2 Search/list  3 Activate/deactivate  4 Set availability");switch(ask("Choice: ")){case "1"->{long id=directory.addDoctor(u,ask("Name: "),ask("Specialization: "),longValue("Department ID: "),ask("Phone: "),new BigDecimal(ask("Consultation fee: ")));System.out.println("Doctor ID: "+id);}case "2"->directory.doctors(u,ask("Name or specialization (blank for all): ")).forEach(System.out::println);case "3"->{long id=longValue("Doctor ID: ");directory.doctorActive(u,id,ask("Active? (y/n): ").equalsIgnoreCase("y"));}case "4"->{directory.availability(u,longValue("Doctor ID: "),integer("Weekday 1=Mon..7=Sun: "),Time.valueOf(LocalTime.parse(ask("Start (HH:mm): "))),Time.valueOf(LocalTime.parse(ask("End (HH:mm): "))),integer("Slot minutes: "));System.out.println("Availability saved.");}default->System.out.println("No action.");}}
 private void departmentMenu(User u)throws SQLException{System.out.println("Departments: 1 Add  2 List  3 Deactivate");switch(ask("Choice: ")){case "1"->System.out.println("Department ID: "+directory.addDepartment(u,ask("Name: "),ask("Description: ")));case "2"->directory.departments(u).forEach(System.out::println);case "3"->{long id=longValue("Department ID: ");if(confirm())directory.deactivateDepartment(u,id);}default->System.out.println("No action.");}}
 private void appointmentMenu(User u)throws SQLException{System.out.println("Appointments: 1 Book  2 List  3 Cancel  4 Complete  5 Mark no-show  6 Reschedule");switch(ask("Choice: ")){case "1"->{long id=appointments.book(u,longValue("Patient ID: "),longValue("Doctor ID: "),LocalDateTime.parse(ask("Start (YYYY-MM-DDTHH:mm): ")),integer("Duration minutes: "),ask("Reason: "));System.out.println("Appointment ID: "+id);}case "2"->{String d=ask("Date (YYYY-MM-DD, blank for all): ");appointments.list(u,d.isBlank()?null:LocalDate.parse(d)).forEach(System.out::println);}case "3"->{long id=longValue("Appointment ID: ");if(confirm())appointments.status(u,id,"CANCELLED");}case "4"->appointments.status(u,longValue("Appointment ID: "),"COMPLETED");case "5"->appointments.status(u,longValue("Appointment ID: "),"NO_SHOW");case "6"->{long id=longValue("Appointment ID: ");long doctor=longValue("New doctor ID: ");LocalDateTime start=LocalDateTime.parse(ask("New start (YYYY-MM-DDTHH:mm): "));int duration=integer("Duration minutes: ");if(confirm()){appointments.reschedule(u,id,doctor,start,duration);System.out.println("Rescheduled.");}}default->System.out.println("No action.");}}
 private void recordMenu(User u)throws SQLException{System.out.println("Medical records: 1 Add for completed visit  2 Patient history");switch(ask("Choice: ")){case "1"->System.out.println("Record ID: "+clinical.createRecord(u,longValue("Appointment ID: "),ask("Symptoms: "),ask("Diagnosis: "),ask("Doctor notes: ")));case "2"->clinical.history(u,longValue("Patient ID: ")).forEach(System.out::println);default->System.out.println("No action.");}}
 private void prescriptionMenu(User u)throws SQLException{System.out.println("Prescriptions: 1 Create  2 List by patient");switch(ask("Choice: ")){case "1"->{long record=longValue("Medical record ID: ");List<String[]> items=new ArrayList<>();do{items.add(new String[]{ask("Medicine: "),ask("Dosage: "),ask("Frequency: "),ask("Duration: "),ask("Instructions: ")});}while(ask("Add another medicine? (y/n): ").equalsIgnoreCase("y"));System.out.println("Prescription ID: "+clinical.prescribe(u,record,items));}case "2"->clinical.prescriptions(u,longValue("Patient ID: ")).forEach(System.out::println);default->System.out.println("No action.");}}
 private void billingMenu(User u)throws SQLException{System.out.println("Billing: 1 Create invoice  2 View invoice  3 Record payment  4 Unpaid invoices");switch(ask("Choice: ")){case "1"->{long id=billing.create(u,longValue("Completed appointment ID: "),new BigDecimal(ask("Subtotal: ")),new BigDecimal(ask("Discount: ")),ask("Line item description: "));System.out.println("Invoice ID: "+id);}case "2"->System.out.println(billing.view(u,longValue("Invoice ID: ")));case "3"->{long id=longValue("Invoice ID: ");BigDecimal amount=new BigDecimal(ask("Amount: "));PaymentMethod method=PaymentMethod.valueOf(ask("Method CASH/CARD/UPI/BANK_TRANSFER: ").toUpperCase(Locale.ROOT));billing.pay(u,id,amount,method,ask("Reference (optional): "));System.out.println("Payment recorded.");}case "4"->billing.unpaid(u).forEach(System.out::println);default->System.out.println("No action.");}}
 private void reportMenu(User u)throws SQLException{if(u.role()==Role.ADMIN||u.role()==Role.BILLING_STAFF){String from=ask("From date (YYYY-MM-DD): ");String to=ask("Through date (YYYY-MM-DD): ");billing.paymentReport(u,LocalDate.parse(from),LocalDate.parse(to)).forEach(System.out::println);billing.unpaid(u).forEach(System.out::println);}else{String from=ask("From date (YYYY-MM-DD): ");String to=ask("Through date (YYYY-MM-DD): ");appointments.report(u,LocalDate.parse(from),LocalDate.parse(to)).forEach(System.out::println);}}
 private void userMenu(User u)throws SQLException{if(u.role()!=Role.ADMIN){System.out.println("User administration is restricted to administrators.");return;}System.out.println("1 Register user  2 Activate/deactivate user");switch(ask("Choice: ")){case "1"->{String name=ask("Username: ");String pass=password("Initial password (12+ characters): ");Role role=Role.valueOf(ask("Role ADMIN/RECEPTIONIST/DOCTOR/BILLING_STAFF: ").toUpperCase(Locale.ROOT));String doctor=role==Role.DOCTOR?ask("Doctor ID: "):"";System.out.println("User ID: "+auth.register(u,name,pass,role,doctor.isBlank()?null:Long.valueOf(doctor)));}case "2"->auth.setActive(u,longValue("User ID: "),ask("Activate? (y/n): ").equalsIgnoreCase("y"));default->System.out.println("No action.");}}
 private void changePassword(User u)throws SQLException{auth.changePassword(u,password("Current password: "),password("New password: "));System.out.println("Password changed. Log in again to refresh your session.");}
 private boolean confirm(){return ask("Confirm? (y/n): ").equalsIgnoreCase("y");}private String ask(String prompt){System.out.print(prompt);return in.nextLine().trim();}private int integer(String p){return Integer.parseInt(ask(p));}private long longValue(String p){return Long.parseLong(ask(p));}
 private String safe(Exception e){if(e instanceof SQLException sql)return "Database operation failed (SQLState "+sql.getSQLState()+"). Check the application logs or database setup.";String m=e.getMessage();return m==null?"unexpected error":m;}
}
